  or coalesce(details->>'p256dh','') !~ '^[A-Za-z0-9_-]{87}=?$' or coalesce(details->>'auth','') !~ '^[A-Za-z0-9_-]{22}(==)?$' then raise exception 'Invalid push subscription' using errcode='22023'; end if;
